    const resolvedValue = resolveRelativeColor(value, opt);
    if (format === VAL_COMP) {
      let res;
      if (resolvedValue instanceof NullObject) {
        if (nullable) {
          res = resolvedValue;
        } else {
          res = RGB_TRANSPARENT;
        }
      } else {
        res = resolvedValue;
      }
      setCache(cacheKey, res);
      return res;
    }
    if (format === VAL_SPEC) {
      let res = '';
      if (resolvedValue instanceof NullObject) {
        res = '';
      } else {
        res = resolvedValue;
      }
      setCache(cacheKey, res);
      return res;
    }
    if (resolvedValue instanceof NullObject) {
      value = '';
    } else {
      value = resolvedValue;
